  "remote.account.deleteWhat": "Eliminar la cuenta la borra junto con tus estaciones, sus dispositivos y las invitaciones hechas en ellas, y tus dispositivos en estaciones de otras personas. Todos se desconectan al instante y las personas que invitaste pierden el acceso. Nexus en tu cuarto de radio sigue funcionando.",
  "remote.account.deleteKept": "Solo conservamos lo que impide una segunda prueba gratuita (huellas de tu dirección, tu indicativo y el ordenador de tu cuarto de radio, y las fechas de tu prueba) y los registros de facturación que exige la ley.",
  "remote.account.deleteSubscription": "Eliminar la cuenta cancela tu suscripción al instante: el acceso termina ahora y la parte no usada del periodo no se reembolsa. Si no han pasado 14 días desde tu primer pago, pide el reembolso antes de eliminarla.",
  "remote.account.deleteConfirm": "Escribe {{word}} para confirmar",
  "remote.account.deleteButton": "Eliminar mi cuenta",
  "remote.account.cancelFailed": "No se pudo cancelar tu suscripción, así que no se eliminó nada. Vuelve a intentarlo en unos minutos.",
  "remote.stationLimitReached": "Esta cuenta ya tiene dos estaciones. Revoca una que no uses antes de vincular otra.",
  "remote.pairingExpired": "Ese código de vinculación ha caducado o ya se ha usado. Consigue uno nuevo en Nexus desde la caseta.",
  "remote.pairingCodeMalformed": "Un código de vinculación tiene dieciséis caracteres, solo dígitos 0-9 y letras a-f. Comprueba si hay una O donde debería ir un cero.",
  "remote.deviceLimitReached": "Esta estación ya tiene todos los navegadores aprobados que permite. Olvida uno que no uses y vuelve a intentarlo.",
  "remote.signInAgain": "Tu sesión ha caducado. Vuelve a iniciar sesión para continuar.",
  "remote.signInRefused": "Se rechazó el inicio de sesión. Si acabas de crear una cuenta, confirma tu correo con el código o el enlace que te enviamos y vuelve a iniciar sesión.",
  "remote.confirmEmailTitle": "Confirma tu correo para terminar",
  "remote.confirmEmailBody": "Tu registro ha funcionado, pero el correo aún no está confirmado. Introduce en la pantalla de registro el código de seis dígitos que te enviamos por correo o, si recibiste un enlace, púlsalo. Luego vuelve aquí para continuar. Si vuelves a ver esta página, el correo aún no está confirmado.",
  "remote.confirmEmailSpam": "¿No ha llegado nada en unos minutos? Busca en la carpeta de spam o correo no deseado un mensaje de Nexus Remote. Un código vale durante quince minutos y un enlace, durante cinco días.",
  "remote.confirmEmailContinue": "Ya he confirmado mi correo — continuar",
  "remote.useDifferentAccount": "Usar otra cuenta",
  "remote.trialActiveElsewhere": "Este correo ya tiene una prueba de Remote en marcha con otro inicio de sesión, por ejemplo Google en lugar de contraseña. Cierra sesión e inicia sesión como lo hiciste la primera vez.",
  "remote.tryLater": "Demasiados intentos. Espera hasta diez minutos y vuelve a intentarlo.",
  "remote.stationOffline": "No se puede alcanzar esa estación. Comprueba que Nexus esté funcionando en la caseta, que Remote esté activado allí (Ajustes → Remoto) y que el ordenador esté despierto y conectado.",
  "remote.sessionEnded": "El acceso remoto a esta estación terminó, así que este navegador se desconectó. Revisa abajo tu periodo de prueba y tus estaciones.",
  "remote.sessionEndedBeta": "El acceso remoto a esta estación terminó, así que este navegador se desconectó. Revisa abajo tus estaciones.",
  "remote.browserPerStation": "Cada estación autoriza sus navegadores por separado, así que este navegador también necesita autorización para esta estación.",
  "remote.sharedComputerHint": "Cerrar sesión deja este navegador autorizado. En un ordenador compartido, pulsa «Retirar la autorización de este navegador» en cada estación antes de cerrar sesión.",
