  "remote.thisStationKey": "Clave de esta estación: {{key}}",
  "remote.stationKey.changed": "La clave de esta estación ha cambiado: el servicio Remote indica ahora una clave distinta de la que guardó este navegador. No se conectará nada hasta que aceptes la clave nueva. Compárala con «Clave de esta estación» en Nexus en la estación y acéptala solo si coinciden.",
  "remote.stationKey.kept": "Clave que guardó este navegador: {{key}}",
