  "remote.revokeHint": "Revocar el acceso desconecta la estación y retira la autorización de todos los navegadores que la usaban. Para volver a usarla, vincúlala de nuevo en la caseta y vuelve a autorizar allí tus navegadores.",
  "remote.revokeStation": "Revocar acceso a la estación",
