  "remote.nativeStationKeyPinned": "El servicio Remote guarda para esta estación una clave distinta de la que usa para firmar su directo, así que los navegadores lo rechazan. Usa Revocar acceso a la estación y vuelve a vincular esta estación.",
  "remote.vaultFailed": "Desbloquea el almacén de credenciales del sistema y vuelve a intentarlo. El acceso remoto permanece desactivado si no puede guardar la credencial de forma segura.",
  "remote.nativeRevoked": "El acceso de esta estación se revocó desde un navegador, por eso ha dejado de conectarse. Aquí no hay nada roto: vuelve a vincularla abajo cuando quieras recuperarla.",
  "remote.nativeTrialEnded": "Tu periodo de prueba de Remote ha terminado, por eso no se pudo añadir esta estación a la cuenta. Tu equipo, tu log y tus ajustes están intactos.",
  "remote.nativeTrialDisabled": "El acceso a Remote de esta cuenta ha sido desactivado, por eso no se pudo añadir esta estación. No es lo mismo que el fin del periodo de prueba. Tu equipo, tu log y tus ajustes están intactos.",
  "remote.nativeCallsignInvalid": "El periodo de prueba de Remote es uno por indicativo, así que primero configura el indicativo de tu estación en Ajustes → Estación y vuelve a vincular esta estación. Tu equipo, tu log y tus ajustes están intactos.",
  "remote.nativeCallsignNotLicensed": "El indicativo de Ajustes → Estación no es una licencia de EE. UU. activa en la lista de licencias de la FCC, por eso no se pudo añadir esta estación. Revisa que no tenga erratas. Una licencia nueva tarda un día aproximadamente en aparecer allí. Tu equipo, tu log y tus ajustes están intactos.",
  "remote.nativeTrialUsedByCallsign": "Este indicativo ya tuvo un periodo de prueba de Remote con otra cuenta, por eso no se pudo añadir esta estación. Si es tu indicativo, escribe a soporte desde el correo que figura en tu licencia. Tu equipo, tu log y tus ajustes están intactos.",
  "remote.nativeTrialUsedOnThisPc": "Este ordenador ya tuvo un periodo de prueba de Remote con otra cuenta, por eso no se pudo añadir esta estación. Tu equipo, tu log y tus ajustes están intactos.",
  "remote.nativeUpdateRequired": "Para añadir una estación a Remote hace falta un Nexus más reciente. Actualiza Nexus y vuelve a vincular esta estación. Tu equipo, tu log y tus ajustes están intactos.",
  "remote.nativeTrialActiveElsewhere": "Este correo ya tiene una prueba de Remote en marcha con otro inicio de sesión, por ejemplo Google en lugar de contraseña, por eso no se pudo añadir esta estación. En tu navegador, cierra sesión, inicia sesión como lo hiciste la primera vez y vuelve a vincular esta estación. Tu equipo, tu log y tus ajustes están intactos.",
