  "remote.native.advanced": "Avanzado",
  "remote.approve": "Autorizar",
  "remote.approval.title": "¿Dejar que «{{browser}}» vea esta estación en directo?",
  "remote.approval.body": "Un navegador con sesión iniciada en tu cuenta de Remote pide ver en directo esta estación y manejarla como lo harías tú aquí, incluida la transmisión. Autorízalo solo si esta clave coincide con la que muestra el navegador: {{key}}.",
  "remote.approval.bodyAgain": "Este navegador ya estaba autorizado, pero no puede ver el directo hasta que lo vuelvas a autorizar aquí. En directo, puede manejar esta estación como lo harías tú aquí, incluida la transmisión. Autorízalo solo si esta clave coincide con la que muestra el navegador: {{key}}.",
  "remote.approval.computerTitle": "¿Dejar que «{{computer}}» maneje esta estación?",
  "remote.approval.computerBody": "Nexus en {{platform}}, con sesión iniciada en tu cuenta de Remote, pide manejar esta estación por internet como lo harías tú aquí, incluida la transmisión. Autorízalo solo si esta clave coincide con la que muestra Nexus en ese ordenador: {{key}}.",
  "remote.approval.computerBodyAgain": "Nexus en {{platform}} ya estaba autorizado, pero no puede conectarse hasta que lo vuelvas a autorizar aquí. Conectado, puede manejar esta estación como lo harías tú aquí, incluida la transmisión. Autorízalo solo si esta clave coincide con la que muestra Nexus en ese ordenador: {{key}}.",
  "remote.approval.deny": "Denegar",
