  "remote.approval.heldBody": "Un navegador inició sesión en tu cuenta de Remote. Ya puede escuchar y sintonizar, y la transmisión espera por ti. Permítelo solo si esta clave coincide con la que muestra el navegador: {{key}}.",
  "remote.approval.heldComputerBody": "Nexus en {{platform}} inició sesión en tu cuenta de Remote. Ya puede escuchar y sintonizar, y la transmisión espera por ti. Permítelo solo si esta clave coincide con la que muestra Nexus en ese ordenador: {{key}}.",
