  "remote.lan.vaultFailed": "Nexus no pudo leer ni guardar en el almacén de credenciales del sistema la clave de red de esta estación y sus ordenadores vinculados. Pulsa Restablecer la identidad de red en Identidad de red, más abajo. Restablecerla quita todos los ordenadores vinculados, así que hay que volver a vincular cada uno.",
