  "aprs.head.packets": "{{count}} paq.",
  "aprs.health.advice.clipping": "La ráfaga está RECORTANDO (pico {{peak}}, {{samples}} muestra(s) a tope) — baja el nivel de salida USB AF del equipo, o el nivel de entrada de Windows de ese dispositivo. El packet aguanta bastante recorte, así que esto cuesta margen y no decodificaciones, pero no hay razón para irse a tope.",
  "aprs.health.advice.quiet": "La ráfaga picó {{peak}}, muy por debajo de la franja sana de {{min}} a {{max}} — sube el nivel de salida USB AF del equipo (IC-9700: SET > Connectors > USB AF Output Level) o el nivel de entrada de Windows de ese dispositivo. Eso da margen frente al ruido; no es por sí solo la causa de que falle un checksum.",
  "aprs.health.dbfs.silence": "silencio",
  "aprs.health.decoding.detail": "{{count}} paquetes decodificados desde que se armó. En vivo {{level}}.",
  "aprs.health.decoding.detail.aged": "{{count}} paquetes decodificados desde que se armó, el último hace {{age}}. En vivo {{level}}.",
  "aprs.health.decoding.label": "{{count}} decodificados",
  "aprs.health.level.peak": "pico de entrada en los últimos 0.1 s: {{db}} dBFS",
  "aprs.health.level.silence": "entrada en los últimos 0.1 s: silencio digital (exactamente cero)",
  "aprs.health.listening.detail": "El audio llega al decodificador y hace rato que no se oyen paquetes — canal tranquilo. En vivo {{level}}. Con el squelch abierto, el siseo debería rondar {{hiss}}; una ráfaga de packet debería picar entre {{min}} y {{max}}.",
  "aprs.health.listening.label": "Escuchando",
  "aprs.health.noCapture.detail": "Armado, pero no llega ni una muestra de audio — el dispositivo de captura no entrega nada. Comprueba que el Dispositivo de entrada (RX) en Ajustes ▸ Equipo ▸ Audio es el equipo (no un micrófono ni un dispositivo desconectado); lo que oyes por el altavoz no te dice lo que está capturando la app.",
  "aprs.health.noCapture.label": "Sin entrada",
  "aprs.health.norf.detail": "Este equipo no cubre {{freq}} MHz, así que no puede recibir APRS por RF. El APRS por RF necesita un equipo de VHF. El feed de internet funciona sin él — actívalo para ver el tráfico APRS que reportan otras estaciones.",
  "aprs.health.norf.label": "Sin equipo de 2 m",
  "aprs.health.off.detail": "El decodificador APRS no está en marcha. Arma el Monitor para decodificar el audio de RX.",
  "aprs.health.off.label": "Monitor apagado",
  "aprs.health.silent.detail": "La entrada está viva y entregando audio, pero está en silencio — normalmente eso solo significa que el squelch está cerrado entre paquetes, que es el aspecto de un canal FM en reposo. Para confirmar el enrutado, abre el squelch: el siseo debería aparecer aquí como nivel. Si sigue marcando silencio con el squelch abierto, el dispositivo de entrada elegido no es el correcto. En vivo {{level}}.",
  "aprs.health.silent.label": "En silencio",
  "aprs.health.unreadable.detail": "{{count}} ráfagas oídas desde que se armó, la última hace {{age}} — ninguna pasó el checksum. Algo de eso es normal: si el squelch abre a mitad de una ráfaga se pierde el arranque del paquete, y un paquete oído a medias nunca puede pasar. Solo es un fallo si no decodifica nunca nada — en ese caso comprueba que el equipo está en {{channel}} en FM.{{advice}} La última ráfaga picó {{burst}}; en vivo {{level}}.",
  "aprs.health.unreadable.label": "{{count}} con CRC fallido",
  "aprs.health.wrongFreq.detail": "El equipo está en {{dial}} — APRS necesita {{want}}. Nada de este canal puede decodificarse como packet APRS, diga lo que diga el nivel de audio. Sintoniza el canal APRS para empezar a oírlo.",
  "aprs.health.wrongFreq.label": "Frecuencia incorrecta",
  "aprs.health.wrongFreqMode.detail": "El equipo está en {{dial}} {{mode}} — APRS necesita {{want}} FM. Nada de este canal puede decodificarse como packet APRS, diga lo que diga el nivel de audio. Sintoniza el canal APRS para empezar a oírlo.",
  "aprs.health.wrongMode.detail": "El equipo está en {{want}} pero en {{mode}} — APRS necesita FM. El audio de packet en FM demodulado como SSB sale ininteligible, así que no decodificará nada por fuerte que sea la señal. Sintoniza el canal APRS para empezar a oírlo.",
  "aprs.health.wrongMode.label": "Modo incorrecto",
  "aprs.inet.chip.title": "{{detail}} Pulsa para los controles del feed de internet.",
