  "assist.keep": "Tus propios ajustes nunca se reescriben. Al finalizar el modo sin asistencia, el decodificador y los feeds vuelven exactamente como los tenías.",
  "assist.sources.off": "Fuentes de asistencia desactivadas: decodificador de CW, DX cluster / RBN, necesarios de PSK Reporter, Super Check Partial, historial de indicativos.",
  "assist.sources.offSince": "Fuentes de asistencia desactivadas desde {{since}}: decodificador de CW, DX cluster / RBN, necesarios de PSK Reporter, Super Check Partial, historial de indicativos.",
  "assist.sources.on": "El decodificador de CW, DX cluster / RBN, los necesarios de PSK Reporter, Super Check Partial y el historial de indicativos están aportando ayuda con indicativos e intercambios.",
  "assist.sources.onSince": "El decodificador de CW, DX cluster / RBN, los necesarios de PSK Reporter, Super Check Partial y el historial de indicativos están aportando ayuda con indicativos e intercambios desde {{since}}.",
  "assist.state.assisted": "ASISTIDO",
  "assist.state.unassisted": "SIN ASISTENCIA",
  "assist.toggle.declare": "Declarar participación sin asistencia",
  "assist.toggle.end": "Finalizar la participación sin asistencia",
  "assist.why.arrl": "En los concursos de la <b>ARRL</b> se llama asistencia de spots y se nombran “PSKReporter, Telnet, webs de spots de DX o sistemas de tablón de anuncios, decodificadores multicanal automáticos”. Single Operator no puede usarla (HCAT.1.1: “no se permite el uso de asistencia de spots”). <b>Single Operator Unlimited</b> sí (HCAT.2.1). El glosario de la ARRL define un decodificador multicanal como el software que “muestra varias señales decodificadas a la vez”. Nexus decodifica una señal cada vez, así que esa definición no describe su decodificador de CW. Sí describe los feeds de cluster, RBN y PSK Reporter.",
  "assist.why.checkRules": "Las bases cambian de un concurso a otro y de un año a otro, así que <b>consulta las bases del concurso en el que participas</b>. Esta nota recoge lo que publican ahora mismo CQ WW y la ARRL. No es un dictamen de categoría.",
  "assist.why.cqww": "La regla VIII.2 de <b>CQ WW</b> cuenta como asistencia para encontrar QSOs “un decodificador de CW, DX cluster, webs de spots de DX … tecnología local o remota de decodificación de indicativos y frecuencias (p. ej., CW Skimmer o Reverse Beacon Network)”. Usar cualquiera de ellos lleva la participación a <b>Single Operator Assisted</b> (V.A.2) en vez de Single Operator (V.A.1).",
  "assist.why.notCovered": "<b>Lo que este interruptor no cubre:</b> los spots de activadores de POTA y SOTA siguen llegando. Ninguna de las dos reglamentaciones nombra esos feeds, pero las dos definen la asistencia de forma lo bastante amplia como para incluirlos, así que desactiva a mano las funciones de POTA/SOTA si participas en un concurso que las cuente.",
  "assist.why.ownDecodes": "Las <b>decodificaciones digitales de tu propio equipo</b>, entre ellas FT8 y FT4, siguen alimentando el panel de Necesarios en modo sin asistencia. Ninguna de las dos reglamentaciones las deja aparte: ambas cuentan como asistencia cualquier tecnología que identifique un indicativo o un multiplicador, así que no uses el panel de Necesarios para encontrar estaciones si tu concurso las cuenta. Tus subidas a PSK Reporter también siguen funcionando, porque la ARRL dice que “generar información de spots para que la usen otras estaciones no se considera asistencia de spots”.",
  "assist.why.summary": "Qué significa esto para tu categoría de concurso",
