  "fieldDay.club.import.title": "Incorpora el diario de concurso de un portátil al log del club, tal como lo habría hecho su sincronización: para un anfitrión que falló o un portátil que nunca sincronizó. El diario se llama fieldday_backup_ más 8 caracteres y .adi, en la carpeta de ajustes de Nexus de ese portátil. Importar el mismo archivo otra vez no añade nada, y no se quita nada del log del club.",
