  "fieldDay.club.give.label": "Dar a este portátil su posición",
  "fieldDay.club.give.title": "Quita esta posición del club al portátil que la tiene ahora y se la da a este. El otro portátil se desconecta y se rechaza, y los contactos que envió como esta posición salen del log del club hasta que vuelva a unirse; este envía al club todos los contactos de su log. La línea del otro portátil tendrá entonces este mismo botón, así que una pulsación equivocada se deshace igual.",
  "fieldDay.club.give.given": "{{name}} recibe su posición en su próximo intento, en menos de 15 segundos, y envía al club todos los contactos de su log. El portátil que la tenía queda rechazado, y su línea aquí puede devolverle la posición.",
