  "gettingStarted.rail.station.label": "Indicativo y locator",
  "gettingStarted.shot.label": "En Nexus",
  "gettingStarted.station.aria": "Paso 1 de 4: indicativo y locator",
  "gettingStarted.station.callout.body": "Cuatro caracteres te sitúan en el centro de un cuadrado de ~100 millas, y toda distancia y todo rumbo que leas se miden desde ese punto. <code>{{full}}</code> es mejor que <code>{{short}}</code>. Un locator mal formado se rechaza sin más — el asistente no deja pasar.",
  "gettingStarted.station.callout.label": "Da los seis caracteres",
  "gettingStarted.station.callsign": "<b>Indicativo</b> — se guarda en mayúsculas. Nexus no arranca PSK Reporter ni el feed RBN/cluster hasta que haya uno válido: 3–10 caracteres, al menos una letra y un dígito.",
  "gettingStarted.station.eyebrow": "Paso 1 de 4 · Tu estación",
  "gettingStarted.station.grid": "<b>Locator</b> — tu locator Maidenhead. QRZ muestra el tuyo.",
  "gettingStarted.station.heading": "¿Quién está en el aire?",
  "gettingStarted.station.lede": "Tu indicativo y tu locator. Todo lo que depende de la ubicación en Nexus — el mapa de propagación, los pasos de satélite, distancias, rumbos, ventanas de DXpedición, la localidad de aperturas en VHF — se calcula a partir de estos dos campos.",
  "gettingStarted.station.name": "<b>Nombre</b> — opcional, en Ajustes ▸ Estación. Alimenta la macro CW <code>{NAME}</code> y el autorrelleno del log.",
  "gettingStarted.station.shot.callsignLabel": "Indicativo",
  "gettingStarted.station.shot.caption": "Asistente ▸ paso 1 · se puede repetir desde Ajustes ▸ Apariencia ▸ Funciones",
  "gettingStarted.station.shot.gridHint": "Locator Maidenhead (qrz.com muestra el tuyo). Da los 6 — con 4 caracteres quedas en el centro de un cuadrado de ~100 millas.",
  "gettingStarted.station.shot.gridLabel": "Locator",
  "gettingStarted.station.shot.next": "Siguiente →",
  "gettingStarted.station.shot.skip": "Lo configuro yo",
  "gettingStarted.station.shot.sub": "Tu locator es el ancla de todo lo que depende de la ubicación — pasos de satélite, propagación, el mapa y las ventanas de DXpedición se calculan a partir de él.",
  "gettingStarted.station.shot.title": "¿Quién está en el aire?",
  "gettingStarted.station.where": "Abre el asistente de primer arranque (aparece al iniciar por primera vez) o <b>Ajustes ▸ Estación</b> cuando quieras.",
  "gettingStarted.title": "Primeros pasos",
  "gettingStarted.wizard.finish": "Finalizar",
  "gettingStarted.wizard.log": "Tu log",
  "gettingStarted.wizard.rig": "Tu equipo",
  "gettingStarted.wizard.station": "Tu estación",
  "gettingStarted.wsjtx.body": "Tu memoria muscular sirve — el doble clic funciona igual, <code>Esc</code> / <code>F4</code> / <code>F6</code> / <code>Alt+1–6</code>, Actividad de Banda anclada abajo, decodificaciones tempranas a 11.8\u00a0s, split Fake-It, salto automático en Hound. Tus ajustes también: apunta el paso 2 al mismo equipo y a los mismos dispositivos de audio que usa WSJT-X, y dale al paso 4 tu <code>wsjtx_log.adi</code>. JTAlert y GridTracker siguen funcionando en cuanto actives <b>WSJT-X UDP API</b> (desactivada por defecto) en Ajustes ▸ Log y conectores ▸ <a>Integraciones y feeds</a>. Su dirección ya coincide con la predeterminada de WSJT-X, así que no hay nada más que configurar, y ven Nexus como un WSJT-X.",
  "gettingStarted.wsjtx.label": "¿Vienes de WSJT-X? El camino corto",
  "gettingStarted.wsjtx.mac": "En un Mac, mantén Fn para las teclas F — o activa \"Usar las teclas F1, F2, etc. como teclas de función estándar\" en Ajustes del Sistema ▸ Teclado, igual que con WSJT-X.",
