  "logbook.tools.bulk.previewFailed": "No se pudo hacer la vista previa",
  "logbook.tools.bulk.uploads": "La edición masiva nunca cambia el indicativo trabajado. Desde aquí no se envía nada. Un STATION_CALLSIGN sustituido por otro indicativo es el indicativo con el que se sube un contacto: se borran sus marcas de subida, la próxima subida lo envía de nuevo con el indicativo nuevo, y se borran sus confirmaciones de LoTW, eQSL y QRZ, emparejadas con el indicativo anterior; las tarjetas QSL de papel se quedan. Rellenar un STATION_CALLSIGN vacío, borrarlo, o añadir o quitar /P no borra ninguna marca de subida ni confirmación. Pero un contacto sin STATION_CALLSIGN se sube con el indicativo de Ajustes, así que rellenarlo o borrarlo puede cambiar el indicativo con el que se envía un contacto a un servicio al que aún no se ha enviado: la confirmación los indica. Cualquier otro campo conserva sus marcas de subida y sus confirmaciones.",
  "logbook.tools.bulk.resend": { "one": "{{count}} de ellos se subió con otro indicativo de estación: se enviará de nuevo con el nuevo.", "other": "{{count}} de ellos se subieron con otro indicativo de estación: se enviarán de nuevo con el nuevo." },
