  "logbook.tools.grids.intro": "Contactos anotados sin locator cuando Nexus conoce el de la estación: el que ella misma transmitió y Nexus oyó en las 24 horas en torno al contacto (ALL.TXT o esta sesión) o, si no, su QTH de casa de una consulta al callbook ya hecha (solo un indicativo sin barra y sin parque, de los últimos 12 meses). Solo se completan los contactos que marque. Un locator oído cuenta como cualquier locator anotado. Un locator del callbook se guarda solo para la distancia y el mapa: no cuenta para ningún diploma de locators, no cubre ninguna necesidad GRID y no se envía a ningún servicio de registro. Un contacto ya subido conserva sus marcas de subida, como con cualquier cambio aquí: no se vuelve a enviar nada y cada servicio conserva lo que recibió.",
