  "logbook.markLotw.body": { "one": "Úsalo si importaste un log que ya habías subido a LoTW por otra vía (Ham2K Polo, TQSL…). Marca el {{formatted}} QSO sin subir como ya presente en LoTW, para que el contador de <b>Subir a LoTW</b> deje de ofrecer reenviarlo. Solo actualiza el registro interno de Nexus — no se envía nada, y tu cuenta y tu log de LoTW quedan intactos. Los QSOs nuevos que hagas después se suben con normalidad.", "other": "Úsalo si importaste un log que ya habías subido a LoTW por otra vía (Ham2K Polo, TQSL…). Marca los {{formatted}} QSOs sin subir como ya presentes en LoTW, para que el contador de <b>Subir a LoTW</b> deje de ofrecer reenviarlos. Solo actualiza el registro interno de Nexus — no se envía nada, y tu cuenta y tu log de LoTW quedan intactos. Los QSOs nuevos que hagas después se suben con normalidad." },
  "logbook.markLotw.cancel": "Cancelar",
