  "logbook.parkStates.buttonTitle": "Lista los contactos de parques y cumbres cuyo estado no es el de su parque, y corrige los que marques",
  "logbook.parkStates.title": "Revisar estados de parques",
  "logbook.parkStates.intro": "Estos contactos de parques y cumbres tienen un estado distinto del de su parque o cumbre, o ninguno: Nexus registraba antes el estado de residencia del activador, según su licencia o su entrada en el callbook. Marca los que quieras cambiar. Nada cambia hasta que pulses el botón, y nada se vuelve a subir. Un contacto confirmado empieza sin marcar.",
