  "logbook.confirmations.button": "Revisar confirmaciones",
  "logbook.confirmations.buttonTitle": "Descarga todo tu historial de LoTW, eQSL y QRZ, de cada servicio que tengas configurado, y lista los contactos cuya confirmación o marca de subida de LoTW asigna el servicio a otro contacto, o a ninguno, para que marques y quites las que quieras",
  "logbook.confirmations.title": "Revisar confirmaciones",
  "logbook.confirmations.intro": "Las versiones anteriores de Nexus podían poner la confirmación de un contacto, de LoTW, eQSL o QRZ, o la marca de que LoTW tiene su subida, en otro contacto con la misma estación, banda y modo en el mismo día UTC. «Revisar» descarga todo tu historial una vez de cada uno de estos servicios que tengas configurado, lo que puede tardar varios minutos en LoTW, y lista cada contacto con una confirmación o marca de subida que los propios registros del servicio asignan a otro contacto, o a ninguno. Una línea empieza marcada solo cuando esos registros lo deciden. Nada cambia hasta que pulses el botón, nada se sube y no se toca ninguna tarjeta QSL en papel.",
  "logbook.confirmations.check": "Revisar",
  "logbook.confirmations.checking": "Descargando todo tu historial de {{service}}…",
  "logbook.confirmations.notChecked": "Sin revisar: {{reason}}",
  "logbook.confirmations.none": "Los registros de LoTW respaldan cada confirmación y marca de subida de LoTW que esta revisión puede juzgar.",
