  "logbook.confirmations.change": "{{service}} ✓ → —",
  "logbook.confirmations.changeUpload": "LoTW: registrada → no subida",
  "logbook.confirmations.why.moved": "La confirmación de {{service}} es de tu contacto de {{time}}",
