  "logbook.confirmations.why.orphan": "{{service}} confirma un QSO de {{time}} que no está en tu log",
  "logbook.confirmations.why.uploadMoved": "La subida que tiene LoTW es de tu contacto de {{time}}",
  "logbook.confirmations.why.uploadOrphan": "LoTW tiene una subida de {{time}} que no está en tu log",
  "logbook.confirmations.why.dateOnly": "sin hora",
  "logbook.confirmations.unticked.dateOnly": "Este contacto, o uno con el que la revisión lo compara, tiene fecha pero no hora, así que los registros de {{service}} no pueden decir a qué contacto pertenece. Márcalo solo si estás seguro.",
  "logbook.confirmations.unticked.notReplayed": "Las versiones anteriores no pudieron poner esta confirmación aquí por elegir el contacto equivocado, así que llegó de otra forma: una importación, un indicativo anterior o una tarjeta en papel que un Nexus antiguo archivó como LoTW. Márcalo solo si estás seguro.",
  "logbook.confirmations.unticked.notReplayedEqsl": "Las versiones anteriores no pudieron poner esta tarjeta aquí por elegir el contacto equivocado, así que llegó de otra forma: una importación, un indicativo anterior o una confirmación que un Nexus antiguo archivó como eQSL. Márcalo solo si estás seguro.",
  "logbook.confirmations.unticked.notReplayedQrz": "Las versiones anteriores no pudieron poner esta confirmación aquí por elegir el contacto equivocado, así que llegó de otra forma, por ejemplo con una importación o un indicativo anterior. Márcalo solo si estás seguro.",
  "logbook.confirmations.unticked.uploadNotReplayed": "Las versiones anteriores no pudieron marcar este contacto por elegir el equivocado, así que la marca llegó de otra forma, por ejemplo con una importación. Márcalo solo si estás seguro.",
  "logbook.confirmations.unticked.tie": "El registro de {{service}} está exactamente igual de cerca de tu otro contacto que de este, así que la revisión no puede decir de cuál es. Márcalo solo si estás seguro.",
  "logbook.confirmations.unticked.orphan": "Ningún contacto de tu log está a menos de 30 minutos del registro de {{service}}: puede que el QSO falte en tu log, o que la hora de este contacto difiera en más de 30 minutos. Márcalo solo si estás seguro.",
  "logbook.confirmations.unticked.insideWindow": "El registro de {{service}} también está a menos de 30 minutos de este contacto, así que puede ser de este contacto. Márcalo solo si estás seguro.",
  "logbook.confirmations.unticked.insideWindowEqsl": "La tarjeta de eQSL también está a menos de 30 minutos de este contacto, y una tarjeta lleva la hora que registró la otra estación, así que puede ser de este contacto. Márcalo solo si estás seguro.",
  "logbook.confirmations.unticked.notToTheMinute": "El registro sin confirmar de {{service}} está cerca de este contacto pero no en su minuto, así que puede ser de otro QSO. Márcalo solo si estás seguro.",
  "logbook.confirmations.badge.card": "tarjeta en papel — conserva el crédito para diplomas",
