  "logbook.purge.syncWarn": "También reinicia tu <b>posición de sincronización de LoTW y eQSL</b>, así que la próxima sincronización vuelve a descargar todo tu historial de confirmaciones en vez de solo las coincidencias recientes. Eso es lo que te devuelve las confirmaciones después de vaciar el log — pero tarda bastante más que una sincronización rutinaria, así que dale tiempo a que termine.",
  "logbook.purge.title": "Elimina todos los contactos del log local",
  "logbook.purge.typeWord": "Escribe <b>{{word}}</b> para confirmar",
  "logbook.purge.warn": { "one": "Esto elimina <b>el {{count}} contacto</b> de tu log local y reescribe el archivo ADIF dejándolo vacío. <b>No</b> quita nada de lo que ya hayas subido a LoTW, QRZ, eQSL o ClubLog. Puedes deshacer todo el vaciado desde el mensaje que aparece a continuación, o más tarde con <b>Deshacer este vaciado</b> en Eliminados recientemente, mientras los Ajustes conserven los contactos eliminados (90 días, salvo que lo hayas cambiado); allí también se pueden restaurar uno a uno. Mientras la radio transmite, un vaciado grande solo se deshace cuando dejas de transmitir. Exporta antes una copia ADIF por si la necesitas más adelante.", "other": "Esto elimina <b>los {{count}} contactos</b> de tu log local y reescribe el archivo ADIF dejándolo vacío. <b>No</b> quita nada de lo que ya hayas subido a LoTW, QRZ, eQSL o ClubLog. Puedes deshacer todo el vaciado desde el mensaje que aparece a continuación, o más tarde con <b>Deshacer este vaciado</b> en Eliminados recientemente, mientras los Ajustes conserven los contactos eliminados (90 días, salvo que lo hayas cambiado); allí también se pueden restaurar uno a uno. Mientras la radio transmite, un vaciado grande solo se deshace cuando dejas de transmitir. Exporta antes una copia ADIF por si la necesitas más adelante." },
