  "phone.mic.aria": "Ganancia de micro",
  "phone.mic.label": "Micro",
  "phone.mic.title": "Ganancia de micrófono — súbela hasta que los picos de SSB rocen la zona del ALC",
  "phone.analog.af.aria": "Volumen AF",
  "phone.analog.af.title": "AF — el volumen del propio equipo. Si tu tarjeta de sonido va conectada a la salida de altavoz o de auriculares, este mando también fija el nivel que oye el decodificador: bajarlo del todo detiene FT8, RTTY y PSK igual que silencia el altavoz. Un equipo con audio USB propio, o una toma ACC/DATA de nivel fijo, no se ve afectado.",
  "phone.analog.af.mutesDecode.label": "¿DECODE?",
  "phone.analog.af.mutesDecode.title": "El AF está casi a cero. Si el decodificador escucha por la salida de altavoz o auriculares, también se ha quedado en silencio. Sube el AF, o alimenta la tarjeta de sonido desde el códec USB o la toma trasera ACC/DATA, que no dependen de este mando.",
  "phone.analog.rf.aria": "Ganancia de RF",
  "phone.analog.rf.title": "Ganancia de RF — la entrada del receptor, no la potencia de transmisión. Bájala en una banda ruidosa para sacar una señal del ruido sobre el que está trabajando el AGC.",
  "phone.analog.sql.aria": "Silenciador",
  "phone.analog.sql.title": "Silenciador — el nivel que debe alcanzar una señal para que la oigas. Normal en FM; en SSB, CW y los modos digitales déjalo completamente abierto, porque un silenciador cerrado corta también el audio que escucha el decodificador en la mayoría de los equipos, incluida la salida USB.",
  "phone.analog.sql.mutesDecode.label": "¿DECODE?",
  "phone.analog.sql.mutesDecode.title": "El silenciador está subido fuera de FM. En la mayoría de los equipos eso corta el audio del decodificador además del altavoz, así que no se decodificará nada hasta que una señal lo abra. Ábrelo del todo para SSB, CW y los modos digitales.",
  "phone.micDax.label": "micro off (DAX)",
  "phone.micDax.title": "El audio DAX nativo de Flex está activado, así que el equipo toma el audio de transmisión de DAX y tu micrófono queda desconectado — en todos los slices y en todos los programas, SmartSDR incluido. Desactiva el audio DAX nativo de Flex en Ajustes ▸ Equipo ▸ Equipo y CAT para usar el micro.",
  "phone.mode.aria": "Modo de Phone",
  "phone.mode.auto.title": "AUTO — banda lateral según la banda (ahora {{sideband}}); un cambio de banda lo vuelve a aplicar",
