  "phone.chain.off": "Apagado",
  "phone.chain.att.aria": "Atenuador",
  "phone.chain.att.title": "El atenuador de entrada, en decibelios — el que publica esta radio. Úsalo cuando una estación vecina fuerte haga bombear el CAG; también te cuesta las señales débiles.",
  "phone.chain.pre.aria": "Preamplificador",
  "phone.chain.pre.title": "El preamplificador de recepción, con el nombre que esta radio da a cada posición — en algunos equipos están numeradas en vez de ir en decibelios. Vale la pena en una banda tranquila; en una ruidosa sube el ruido junto con la señal.",
  "phone.chain.mon.aria": "Nivel del monitor",
  "phone.chain.mon.title": "Cuánto te devuelve la radio tu propia voz mientras transmites. Solo se oye en transmisión, así que bajarlo nunca puede silenciar un decodificador — eso es el AF.",
  "phone.prov.rig": "Confirmado por la radio.",
  "phone.prov.cmd": "Tal como se ordenó: esta radio no informa de {{plate}} por CAT, así que esto es lo último que envió Nexus.",
  "phone.tx.lastOver": "{{watts}} W en la última transmisión",
  "phone.tx.repeaterMark": "desplazamiento de repetidor",
  "phone.tx.voxWarn": "El VOX está activado: la radio se activa sola con el micrófono. Stop TX no puede desactivar un transmisor retenido por VOX.",
  "phone.pane.log.title": "Log",
  "phone.txContract.aria": "Contrato de transmisión — lo que sale cuando aprietas el PTT",
  "phone.txContract.freq.title": "La frecuencia en la que realmente se emitirá tu próxima transmisión — la respuesta del propio motor, con el split confirmado y el desplazamiento XIT ya incluidos. En split esta NO es tu frecuencia de recepción.",
  "phone.txContract.freq.commanded.title": "Nexus ha deducido esta frecuencia de lo que ordenó y no puede confirmarla entera contra la radio: o no hay enlace CAT, o hay XIT en juego y el clarificador es de solo escritura, así que un desplazamiento puesto en la radio no aparecería aquí.",
  "phone.txContract.noEmission.title": "Esta estación no informa de una frecuencia de transmisión. Nexus no pondrá tu dial de recepción en su lugar — en split son números que no tienen relación.",
  "phone.txContract.repeaterShift.title": "Nexus no puede indicar tu frecuencia de transmisión en FM a través de un repetidor: el desplazamiento lo aplica la radio y no está en la frecuencia que informa el motor, así que poner un número aquí sería tu frecuencia de escucha con una etiqueta de transmisión. Comprueba el desplazamiento en Ajustes ▸ Radio, o léelo en la radio.",
  "phone.txContract.mode.title": "El modo en que saldrá tu próxima transmisión, y de dónde lo ha sacado Nexus. Es la misma lectura que escribe el cuaderno de guardia, así que lo que ves aquí y lo que queda registrado no pueden discrepar.",
  "phone.txContract.split.title": "A qué distancia queda tu frecuencia de transmisión de tu dial de recepción (kHz)",
  "phone.txContract.split.commanded.title": "Nexus ha pedido este split a la radio. La instantánea no trae la confirmación de la propia radio, así que se muestra como ordenado y no como leído — comprueba la radio si el pile-up no te oye donde esperas.",
  "phone.txContract.xit.title": "Transmit incremental tuning — el desplazamiento añadido a tu frecuencia de transmisión (Hz)",
  "phone.txContract.xit.commanded.title": "Nexus no puede leer el XIT de ninguna radio, así que esto es lo que Nexus ordenó y no necesariamente dónde está el transmisor. Un desplazamiento puesto con el clarificador de la radio no aparecerá aquí.",
  "phone.txContract.power.title": "Tu ajuste de potencia y la salida que la radio midió por última vez. Sin marca: el ajuste es la lectura de la radio cuando CAT informa de una, y el último valor ordenado si no, y nada dice cuál de los dos es.",
