  "roam.controls.legend": "Controles",
  "roam.disclaimer": "<b>No es privado — se anuncia en claro.</b> El QSY coordinado os lleva a ti y a otra estación juntos a un canal nuevo, con el cambio enviado en texto plano (la Part 97 de la FCC prohíbe el cifrado y ocultar el significado, y tu indicativo se identifica cada 10 min). Despista a un escucha <em>ocasional</em> parado en la frecuencia vieja — <em>no</em> te esconde de nadie con un receptor de banda ancha, que puede seguirte. Úsalo contra el QRM y para una discreción modesta, nunca para el secreto.",
