  "sat.lane.blocked.detail": "Celestrak ha rechazado las descargas directas de elementos (HTTP 403/404) — los intentos directos se paran durante 24 h. El espejo de hamradiotools.io sigue reintentando; los elementos pueden envejecer hasta que llegue.",
