  "sat.lane.mostlyStale.detail": "La mayoría de los juegos de elementos que tienes han pasado la línea de caducidad de 14 días — {{label}}. El satélite típico sigue al día, así que la edad se lee tranquila; en el resto del catálogo las horas de pasada, el apuntamiento y el Doppler se están desviando. Actualiza desde la sección Satélites o en Ajustes ▸ Equipo ▸ Elementos orbitales.",
