  "sat.lockOn.title": "Vuelve a aplicar el transpondedor que elegiste — enruta, pone la banda y el modo, escribe las dos patas y te vuelve a centrar en la banda de paso. Úsalo tras mover el dial fuera del transpondedor a mano, o cuando el equipo haya vuelto a otro sitio.",
  "sat.log.note": "Anota el contacto desde tu dial, exactamente igual que los paneles de log de Fonía y CW. En el downlink de un satélite que LoTW reconoce — el que estás trabajando, o el último que trabajaste hasta que elijas otro — Nexus lo marca por ti: escribe los campos ADIF PROP_MODE y SAT_NAME, así que el contacto cuenta para el crédito de satélite de LoTW <b>y para los totales de satélite del propio Nexus</b>. Todo lo demás se anota como un contacto normal, y en 2 m su locator cuenta para tu VUCC terrestre, que un contacto por satélite no da. Para marcar uno tú mismo, añade <b>los dos</b> campos — uno sin el otro se rechaza al firmar.",
  "sat.log.note.title": "Anota el contacto desde tu dial, exactamente igual que los paneles de log de Fonía y CW. En el downlink de un satélite que LoTW reconoce — el que estás trabajando, o el último que trabajaste hasta que elijas otro — Nexus lo marca por ti: escribe los campos ADIF PROP_MODE y SAT_NAME, así que el contacto cuenta para el crédito de satélite de LoTW y para los totales de satélite del propio Nexus. Todo lo demás se anota como un contacto normal, y en 2 m su locator cuenta para tu VUCC terrestre, que un contacto por satélite no da. Para marcar uno tú mismo, añade LOS DOS campos — uno sin el otro se rechaza al firmar.",
