  "sat.transponder.txMode.forecast": "Banda lateral de TX: este satélite va con {{up}} en subida / {{down}} en bajada (SatNOGS). En cuanto tu asignación de subida esté confirmada para el equipo en uso, el VFO de TX (split) se pone igual mientras corre una pasada en seguimiento.",
