  "settings.iotaList.consent.hint": "La lista de IOTA Ltd (© RSGB e IOTA Ltd), descargada de iota-world.org en este ordenador para su uso personal y renovada como mucho una vez al mes. Da nombre a los grupos de islas y señala una referencia que no lo es. Al desactivarla se borra la copia.",
