  "settings.confirmations.hrdlog.code.label": "Código de subida de HRDLog.net",
  "settings.confirmations.hrdlog.code.placeholder": "tu código de subida de hrdlog.net",
  "settings.confirmations.hrdlog.upload.hint": "Envía cada QSO anotado a HRDLog.net (necesita el código de subida de arriba). HRDLog.net es un sitio de log en vivo y diplomas — <b>no</b> es una fuente de confirmación de la ARRL, así que subir aquí nunca da crédito DXCC/WAS.",
  "settings.confirmations.hrdlog.upload.label": "Subir QSOs a HRDLog.net automáticamente",
  "settings.confirmations.legend": "Confirmaciones",
  "settings.confirmations.lotw.adifLocation.aria": "Firmar las subidas a LoTW desde la ubicación del ADIF",
  "settings.confirmations.lotw.adifLocation.hint": "Actívalo si has configurado TQSL con <em>\"use the location in the ADIF file\"</em> y no creas Station Locations con nombre (útil si viajas). Nexus estampa entonces tu indicativo + locator (STATION_CALLSIGN / MY_GRIDSQUARE) en la subida y omite el argumento <code>-l</code>, de modo que TQSL firma con esos y el Station Location de arriba no hace falta. <b>El lote entero se firma con tu locator actual de arriba</b>, así que si operas desde más de un sitio, sube <em>antes</em> de moverte — o los contactos anteriores quedarán firmados con el locator nuevo. La excepción es un contacto de un concurso de VHF incorporado al Log: se firma con el locator que enviaste en su intercambio (como rover, el de ese momento).",
  "settings.confirmations.lotw.adifLocation.label": "Firmar desde la ubicación del ADIF (viajeros)",
  "settings.confirmations.lotw.autoUpload.blocked": "No disponible mientras “Firmar desde la ubicación del ADIF” esté activo: un lote sin vigilancia firmaría contactos antiguos con donde estás AHORA.",
  "settings.confirmations.lotw.autoUpload.hint": "Cada pocas horas, Nexus entrega a TQSL tus contactos sin subir en un solo lote y TQSL los firma y los envía — lo mismo que hace el botón <b>Upload to LoTW</b> del Log, pero con temporizador. Necesita TQSL instalado y el Station Location de arriba. Si un lote es rechazado, esto se detiene y te espera en vez de reintentar; guarda cualquier ajuste de LoTW para volver a arrancarlo.",
  "settings.confirmations.lotw.autoUpload.label": "Subir a LoTW automáticamente",
  "settings.confirmations.lotw.autoUpload.lastRun": "Última ejecución: {{when}}.",
  "settings.confirmations.lotw.password.hint": "Tu contraseña de la <b>web</b> de LoTW (no la del certificado TQSL). Se guarda en el llavero del sistema, nunca en disco; no se vuelve a mostrar tras pulsar Fijar.",
  "settings.confirmations.lotw.password.label": "Contraseña de LoTW",
  "settings.confirmations.lotw.password.placeholder": "contraseña de la web de LoTW",
  "settings.confirmations.lotw.stationLocation.hint": "Para <b>subir</b> a LoTW (el botón \"Upload to LoTW\" del Log). La firma la hace tu <b>TQSL</b> instalado contra ese Station Location — configúralo antes en TQSL; el nombre debe coincidir exactamente. Nexus no guarda ningún certificado ni contraseña.",
  "settings.confirmations.lotw.stationLocation.label": "Station Location de LoTW",
  "settings.confirmations.lotw.stationLocation.placeholder": "nombre exacto del Station Location de TQSL",
  "settings.confirmations.lotw.sync.action": "Descargar confirmaciones",
  "settings.confirmations.lotw.sync.busy": "Descargando…",
  "settings.confirmations.lotw.sync.hint": "Esto solo trae confirmaciones <b>hacia abajo</b>. Para enviar tus contactos <em>a</em> LoTW, usa <b>Upload to LoTW (N)</b> en el Log. Trae las confirmaciones nuevas a tu log y marca cuáles de tus subidas constan ya en LoTW (para que se lean como “esperando al otro operador” y no como “nunca subido”). La primera descarga cubre todo tu historial (puede ser lenta); las siguientes son incrementales.",
  "settings.confirmations.lotw.redownload.action": "Descargar todo de nuevo",
  "settings.confirmations.lotw.redownload.title": "Para confirmaciones que una descarga anterior no trajo: vuelve a descargar todo tu historial de LoTW.",
  "settings.confirmations.lotw.redownload.confirm.title": "¿Descargar de nuevo todo tu historial de LoTW?",
  "settings.confirmations.lotw.redownload.confirm.body": "Esto pide a LoTW todas las confirmaciones de tu cuenta, no solo las nuevas, y empieza enseguida. Es una descarga grande y puede tardar varios minutos. Tus contactos registrados y sus confirmaciones no cambian.",
  "settings.confirmations.lotw.sync.label": "Confirmaciones de LoTW",
  "settings.confirmations.lotw.tqslPath.hint": "Solo si TQSL está instalado en una ruta no estándar; si no, déjalo vacío para detectarlo solo.",
  "settings.confirmations.lotw.tqslPath.label": "Ruta de TQSL (opcional)",
