  "settings.confirmations.lotw.username.hint": "Suele ser tu indicativo, pero no siempre — usa el login de tu cuenta LoTW. Guarda los ajustes para aplicar.",
  "settings.confirmations.lotw.username.label": "Usuario de LoTW",
  "settings.confirmations.lotw.username.placeholder": "tu login de la cuenta LoTW",
  "settings.confirmations.qrz.apiKey.forget.title": "Quitar la clave del Logbook guardada del llavero del sistema",
  "settings.confirmations.qrz.apiKey.hint": "Una clave <b>aparte</b> (no la contraseña de acceso) de la página de ajustes de tu logbook QRZ — se usa para subir los QSOs anotados.",
  "settings.confirmations.qrz.apiKey.label": "API key del Logbook de QRZ",
  "settings.confirmations.qrz.apiKey.placeholder": "de la página de ajustes de tu logbook QRZ",
  "settings.confirmations.qrz.autoSync.hint": "A medida que la gente confirma en QRZ, las confirmaciones entran solas — no hace falta pulsar Sincronizar. Tras la primera vez solo se descarga lo que CAMBIÓ. Las confirmaciones de QRZ aparecen como confirmadas pero nunca cuentan para DXCC ni WAS, que necesitan LoTW o una tarjeta.",
  "settings.confirmations.qrz.autoSync.label": "Traer las confirmaciones automáticamente",
  "settings.confirmations.qrz.autoSync.lastPull": "Última descarga: {{when}}.",
  "settings.confirmations.qrz.password.hint": "Tu contraseña de acceso a QRZ.com — <b>es lo que hace funcionar las consultas de callbook</b> (nombre, QTH, locator), y es distinta de la API key del Logbook de QRZ en Log y conectores (esa clave solo sube QSOs). Se guarda en el llavero del sistema, nunca en disco. El locator y el estado necesitan una suscripción XML de QRZ; las cuentas gratuitas solo devuelven nombre/dirección/país.",
  "settings.confirmations.qrz.password.label": "Contraseña de QRZ",
  "settings.confirmations.qrz.password.placeholder": "contraseña de la cuenta QRZ.com",
  "settings.confirmations.qrz.sync.action": "Sincronizar desde QRZ ahora",
  "settings.confirmations.qrz.sync.busy": "Sincronizando…",
  "settings.confirmations.qrz.sync.hint": "Trae tu logbook de QRZ <b>hacia abajo</b> — añade los QSOs que anotaste en otro sitio (p. ej. una app de móvil en el campo) y marca los contactos confirmados en QRZ. Las confirmaciones de QRZ cuentan como confirmaciones pero <b>no</b> para DXCC/WAS. Se puede repetir sin problema (deduplica). Necesita la API key del Logbook de arriba.",
  "settings.confirmations.qrz.sync.label": "Sincronización bidireccional",
  "settings.confirmations.qrz.sync.title": "TRAE tu logbook online de QRZ y lo fusiona — descarga los QSOs que anotaste en otro sitio junto con sus confirmaciones",
  "settings.confirmations.qrz.upload.hint": "Envía cada QSO anotado a tu logbook de QRZ (necesita la API key del Logbook de arriba).",
  "settings.confirmations.qrz.upload.label": "Subir QSOs a QRZ automáticamente",
  "settings.confirmations.qrz.username.hint": "Se usa para buscar el nombre y el locator de un indicativo al anotar. Guarda los ajustes para aplicar.",
  "settings.confirmations.qrz.username.label": "Usuario de QRZ",
  "settings.confirmations.qrz.username.placeholder": "tu login de la cuenta QRZ.com",
  "settings.confirmations.repeaterbook.token.forget.title": "Quitar el token de RepeaterBook guardado del llavero del sistema",
  "settings.confirmations.repeaterbook.token.hint": "Opcional. Sin token, la sección <b>Repetidores</b> usa el directorio abierto hearham.com. Añade un token personal (de la página <b>API Apps</b> de tu cuenta RepeaterBook) para tirar de RepeaterBook.com con tu propia cuenta. Se guarda en el llavero del sistema. El acceso compartido a RepeaterBook para todos los usuarios de Nexus está pendiente de la aprobación de RepeaterBook; si RepeaterBook no responde, Repetidores vuelve a hearham.com.",
