  "settings.features.profile.hint.custom": "Personalizado — un conjunto de funciones mixto. Elige un único objetivo arriba para volver a sus valores por defecto.",
  "settings.features.profile.hint.preset": "Elige un objetivo para fijar unos valores sensatos — todas las funciones siguen siendo conmutables abajo. Cambiar de perfil vuelve a aplicar su conjunto.",
  "settings.features.profile.label": "Perfil",
