  "settings.js8.schedule.label": "Cambiar de frecuencia según un horario",
  "settings.js8.schedule.hint": "Apagado por defecto, como en JS8Call. Activado, Nexus cambia la frecuencia de la radio POR SÍ SOLO a las horas de abajo, sin nadie frente a la radio: primero un aviso y, 30 segundos después, el cambio, salvo que lo canceles. Nunca mientras transmite ni mientras sale un mensaje.",
