  "settings.phone.voiceMic.default": "El mismo que la entrada de audio (por defecto)",
  "settings.phone.voiceMic.hint": "El micro que se usa al GRABAR un mensaje del keyer de voz. Por defecto graba del dispositivo de entrada de audio — pero en un montaje digital eso es el audio de RX del equipo, así que grabarías la banda, no tu voz. Elige aquí tu micro real. Si no se puede abrir, la grabación vuelve al dispositivo de entrada (nunca queda muda).",
  "settings.phone.voiceMic.label": "Micro de voz (grabación)",
  "settings.pounce.legend": "Pounce — alerta de nuevo",
  "settings.pounce.note": "Te interrumpe en el INSTANTE en que una estación necesaria aparece en el cluster o la RBN, en vez de esperar a que el panel de spots se refresque. Suena un tono fuerte tanto si Nexus es la ventana que estás mirando como si no, y un banner ofrece trabajarla con un clic. Desactivado hasta que lo actives. Lo raro que es \"raro\" depende de tus propios totales: si vas por las primeras cien entidades casi todo spot de DX es nuevo y esto no callaría nunca. Empieza por <em>Solo entidad DXCC nueva</em> cuando tu log esté lo bastante avanzado como para que un nuevo sea un acontecimiento de verdad. Cada estación alerta una vez por banda y modo.",
  "settings.pounce.threshold.atno": "Solo entidad DXCC nueva",
  "settings.pounce.threshold.atnoOrZone": "Entidad o zona CQ nueva",
  "settings.pounce.threshold.atnoZoneOrState": "Entidad, zona, estado de EE. UU. o grupo IOTA nuevo",
  "settings.pounce.threshold.label": "Avisarme de",
  "settings.pounce.threshold.off": "Off (por defecto)",
  "settings.profiles.delete.action": "Eliminar",
  "settings.profiles.legend": "Perfiles",
  "settings.profiles.list.hint": "Cambia de golpe todo un montaje de equipo / antena / CAT / bandas.",
  "settings.profiles.list.label": "Perfiles guardados",
  "settings.profiles.list.none": "— Selecciona un perfil —",
  "settings.profiles.load.action": "Cargar",
  "settings.profiles.load.title": "Aplica este perfil — se fusiona con tus ajustes actuales. El indicativo, la clase de licencia, la lista de equipos y el historial de sincronización nunca vienen de un perfil, y todo lo que el perfil no conozca mantiene su valor actual.",
  "settings.profiles.loaded": "Perfil \"{{name}}\" cargado",
  "settings.profiles.save.action": "Guardar",
