  "settings.workspace.contrast.hint": "M\u00e1s contraste entre el texto y el fondo con el tema que uses, al tama\u00f1o que ya tienes. Act\u00edvalo si cuesta leer la pantalla: no cambia la escala de la interfaz.",
  "settings.workspace.contrast.hint.field": "El modo campo est\u00e1 activo, as\u00ed que el alto contraste ya se aplica. Este ajuste es tu elecci\u00f3n permanente y es lo que conserva la pantalla al desactivar el modo campo.",
