  "setup.about.sub": "Tu respuesta decide qué pantallas empiezan activadas, cuánto de Ajustes se abre al principio y qué ofrece el último paso. Cámbiala cuando quieras en Ajustes ▸ Estación. Todas las funciones siguen en Ajustes y en su búsqueda, elijas lo que elijas.",
  "setup.about.newToHobby": "Nuevo en la afición",
  "setup.about.newToHobby.blurb": "Una licencia nueva, o en camino. Nexus empieza con FT8, el log y los mapas, y te guía en tu primer contacto.",
  "setup.about.newToDigital": "Nuevo en digitales",
