  "firstContact.title": "Tu primer contacto FT8",
  "firstContact.sub": "Leer esto no cambia ningún ajuste ni transmite nada.",
  "firstContact.step.listen": "Primero escucha. Con la radio conectada y en una frecuencia de FT8, las estaciones que Nexus oye aparecen en Actividad de banda cada 15 segundos.",
  "firstContact.step.cq": "Una línea con CQ es una estación que llama a cualquiera. Un número de dB más alto es una señal más fuerte.",
  "firstContact.step.answer": "Haz doble clic en esa línea para responder. Eso activa TX: Nexus llama a la estación enseguida o en el siguiente periodo y envía cada mensaje del contacto por ti.",
  "firstContact.step.answer.manual": "Haz doble clic en esa línea para responder. TX sigue desactivado porque {{setting}} está desactivado en Ajustes: pulsa {{txOff}} para activar TX y Nexus llamará a la estación y enviará cada mensaje del contacto por ti.",
  "firstContact.step.tx": "TX empieza desactivado cada vez que se abre Nexus ({{txOff}}). {{stop}} termina una transmisión al instante; {{txOn}} desactiva TX al terminar el periodo en curso.",
