  "shell.lane.recording.message": "GRABANDO",
  "shell.lane.parsecStop.message": "PARSEC CAÍDO — TX DETENIDO",
  "shell.lane.parsecStop.detail": "Tu sesión de Parsec se cayó (o el registro de Parsec dejó de responder) a las {{time}} UTC, así que Nexus detuvo: {{what}}. No se volvió a arrancar nada; vuelve a transmitir cuando regreses.",
  "shell.lane.parsecStop.what.ptt": "PTT enclavado",
  "shell.lane.parsecStop.what.rtty": "TX continuo de RTTY",
  "shell.lane.parsecStop.what.psk": "TX continuo de PSK",
  "shell.lane.parsecStop.what.tune": "Tune",
  "shell.lane.slotKeyRefused.message": "PTT RECHAZADO — TX DETENIDO",
  "shell.lane.slotKeyRefused.detail": "La radio no aceptó el PTT a las {{time}} UTC ({{why}}), así que ese turno no se envió y TX se apagó. Revisa tu método de PTT y el CAT/puerto, y luego vuelve a activar TX.",
  "shell.lane.slotKeyRefused.flex.notYetDax": "Nexus no puso en el aire el turno de {{mode}} a las {{time}} UTC: el audio DAX nativo de Flex está activado, pero la radio aún no tomaba su audio de transmisión de Nexus por DAX. No se envió nada y TX se apagó. Nexus termina de preparar la radio en un momento; luego vuelve a activar TX.",
  "shell.lane.slotKeyRefused.flex.daxUnfed": "Nexus no puso en el aire el turno de {{mode}} a las {{time}} UTC: el audio DAX nativo de Flex está desactivado, pero la radio aún tomaba su audio de transmisión por DAX, como Nexus la había configurado, y ahora nada alimenta DAX. No se envió nada y TX se apagó. Nexus vuelve a poner la radio en su entrada de micrófono en un momento; luego vuelve a activar TX.",
  "shell.lane.slotKeyRefused.txAudio": "Nexus no puso la radio en transmisión a las {{time}} UTC porque la salida de audio de transmisión no se pudo abrir ({{why}}). No se envió nada y TX se apagó. Revisa el Dispositivo de salida (TX) en Ajustes (puede que otro programa lo esté usando o que esté desconectado) y luego vuelve a activar TX.",
  "shell.lane.slotUnkeyFailed.message": "FALLO AL DESACTIVAR EL PTT — TX DETENIDO",
  "shell.lane.slotUnkeyFailed.detail": "La radio no aceptó la desactivación del PTT a las {{time}} UTC ({{why}}), así que TX se apagó. Puede que siga transmitiendo: revisa la radio ahora. Nexus sigue desactivando el PTT hasta que la radio lo acepte. Vuelve a activar TX cuando la radio esté recibiendo.",
  "shell.lane.slotAudioLost.message": "TURNO TERMINADO — TX DETENIDO",
  "shell.lane.slotAudioLost.detail": "La vía que lleva el audio de un turno al equipo (DAX de Flex o TCI) se cortó a las {{time}} UTC en medio del turno, así que el resto habría salido en silencio. Nexus terminó el turno ahí y apagó TX. Vuelve a activar TX para continuar.",
  "shell.lane.slotOverDropped.message": "TURNO DESCARTADO — ACTIVACIÓN TARDÍA",
  "shell.lane.slotOverDropped.detail": "Este turno se descartó: la radio no se puso en transmisión hasta las {{time}} UTC, {{late}} después de terminar tu periodo (CAT lento), así que Nexus la quitó de transmisión de inmediato, no envió nada y dejó TX activado para tu siguiente turno. La Operación en Split envía a la radio sus comandos antes de cada activación, lo que en un enlace CAT lento puede tardar segundos: si vuelve a ocurrir, revisa el enlace CAT y la Operación en Split en Ajustes.",
  "shell.lane.pttRefused.message": "PTT RECHAZADO",
  "shell.lane.pttRefused.detail": "Nexus no puso en el aire el turno de {{mode}} a las {{time}} UTC: la radio aún tomaba su audio de transmisión por DAX, como Nexus la había configurado, no de su micrófono, así que tu voz no habría salido. No se envió nada. Suelta el PTT y Nexus vuelve a poner la radio en su entrada de micrófono en un momento; luego vuelve a pulsar el PTT.",
  "shell.lane.voiceDropped.message": "MENSAJE DE VOZ DESCARTADO",
  "shell.lane.voiceDropped.noDax": "Nexus no reprodujo el mensaje de voz a las {{time}} UTC: la radio no pasó su audio de transmisión a DAX en 2 segundos, así que no se transmitió nada. El mensaje se descartó, no se retuvo; vuelve a pulsar su tecla.",
  "shell.lane.voiceDropped.keyed": "Nexus no reprodujo el mensaje de voz a las {{time}} UTC: otra cosa ya transmitía o puso la radio en transmisión antes (tu micrófono o el PTT, una portadora de Tune, otro programa), así que no se transmitió nada. El mensaje se descartó, no se retuvo.",
  "shell.lane.clockRepairHold.message": "REPARACIÓN DEL RELOJ — TX EN ESPERA",
  "shell.lane.clockRepairHold.detail": "Nexus está reparando el reloj de este ordenador. Ninguna transmisión empieza hasta que termine la reparación, dos minutos como máximo, para que el reloj no se mueva en mitad de una pasada.",
  "shell.lane.txOnHeld.message": "TX EN ESPERA — FALTA APROBACIÓN",
  "shell.lane.txOnHeld.detail": "Un dispositivo Remote recién conectado espera tu aprobación. Pulsa «Permitir transmitir» en Ajustes ▸ Remoto para que pueda transmitir.",
  "shell.lane.txPowerZero.detail": "El equipo indica 0% de potencia y la transmisión está armada — activará el PTT y no saldrá nada al aire. Revisa el deslizador Pwr y la potencia del propio equipo para ESTE modo: los Yaesu guardan un nivel distinto para SSB, DATA, CW y AM.",
  "shell.lane.txPowerZero.message": "SIN POTENCIA RF",
  "shell.loading": "Conectando con Nexus…",
  "shell.log.movedOn": "Ese contacto ya se había anotado o descartado: no se anotó nada y ahora se muestra el que estaba esperando.",
