  "quit.logbook.refused.title": "No se pudo guardar tu libro de guardia",
  "quit.logbook.refused.body": { "one": "{{count}} cambio no se pudo escribir en el libro de guardia: {{reason}}. Esperar más no lo guardará.", "other": "{{count}} cambios no se pudieron escribir en el libro de guardia: {{reason}}. Esperar más no los guardará." },
  "quit.logbook.keepTrying": "Seguir intentando",
  "quit.logbook.quitWithout": { "one": "Salir sin el último cambio", "other": "Salir sin los últimos {{count}} cambios" },
