  "quit.logbook.retry.body": { "one": "{{count}} cambio no se pudo escribir en el libro de guardia: {{reason}}. «Seguir intentando» lo vuelve a enviar.", "other": "{{count}} cambios no se pudieron escribir en el libro de guardia: {{reason}}. «Seguir intentando» los vuelve a enviar." },
  "shell.logSave.retrying": "Nexus no pudo guardar un cambio en el libro de guardia: {{reason}}. Conserva el cambio en memoria y lo vuelve a enviar hasta que el libro de guardia lo acepte. No se pierde nada mientras Nexus siga abierto.",
  "shell.logSave.held": "El libro de guardia rechazó un cambio de forma definitiva: {{reason}}. Nexus lo conserva en memoria durante esta sesión y te pregunta por él al salir. El registro de diagnóstico tiene los detalles.",
  "shell.logSave.saved": "El libro de guardia vuelve a estar guardado: todos los cambios que había rechazado ya están en el disco.",
  "shell.logStore.network": "Nexus no abrió la base de datos del libro de guardia porque tu carpeta de datos está en una unidad de red, donde una base de datos puede dañarse por cómo funciona el bloqueo de archivos a través de la red. No se pierde nada: esta sesión guarda tu log en log.adi, como antes. Para usar la base de datos, mueve la carpeta de datos a una unidad dentro de este ordenador en Ajustes ▸ Config ▸ Carpeta de datos y registro.",
