  "topbar.clock.corrected.label": "reloj {{offset}} ✓",
  "topbar.clock.corrected.title": "El reloj del PC va {{offset}} respecto a UTC y Nexus ya lo está corrigiendo — las ventanas de transmisión y decodificación caen en la rejilla UTC real. Medido hace {{age}}, con {{servers}} servidores de hora coincidentes.",
